from common import *
import numpy as np, pandas as pd, pickle

def model(job):
    if job=='archived-new':p=ROOT/'backtest/result/horizonp50_20261105_h20_s3000/run_01/artifacts_root/artifacts/trained_model'
    else:p=ROOT/read(BASE/'docs'/f'{PREFIX}-{job}.json')['model']['path']
    with p.open('rb') as f:return pickle.load(f).model

if __name__=='__main__':
    register_adapter(__file__)
    a,b=sys.argv[1:3];ma,mb=model(a),model(b);n=min(ma.num_trees(),mb.num_trees())
    vm=read(VALID);cached=pd.read_pickle(VALID.parent/vm['blocks']['frame']['path']);frame=cached['frame'];tradable=cached['tradable'];del cached
    frame=frame.loc[frame.index.get_level_values('datetime')<=pd.Timestamp('2026-07-23')]
    counts=np.zeros(n,dtype=np.int64);rows=0;prefix4rows=0;total=0;hashes=[hashlib.sha256(),hashlib.sha256()];pa=[];pb=[]
    for i in range(0,len(frame),100000):
        x=frame.iloc[i:i+100000]['feature'].values
        la=ma.predict(x,num_iteration=n,pred_leaf=True,num_threads=8)
        lb=mb.predict(x,num_iteration=n,pred_leaf=True,num_threads=8)
        pa.append(ma.predict(x,num_threads=8));pb.append(mb.predict(x,num_threads=8))
        delta=la!=lb;counts+=delta.sum(axis=0);rows+=np.any(delta,axis=1).sum();prefix4rows+=np.any(delta[:,:min(4,n)],axis=1).sum();total+=len(x)
        for h,v in zip(hashes,[la,lb]):h.update(v.astype('<i4').tobytes())
    result={'a':a,'b':b,'panel':'identical exit-bounded validation features','rows':total,'common_selected_trees':n,'different_leaf_index_rows':int(rows),'first_four_trees_different_leaf_index_rows':int(prefix4rows),'different_leaf_index_count_per_tree':counts.tolist(),'leaf_index_stream_sha256':[h.hexdigest() for h in hashes],'limitation':'Different leaf numbers may also reflect equivalent re-numbered topology; equal leaf indices are interpreted alongside tree split comparison, not alone.'}
    from backtest.scripts.evaluate.eval_ic_multi_pool import daily_head_panel
    from compare import difference
    pa=np.concatenate(pa);pb=np.concatenate(pb);result['selected_prediction']=difference(pa,pb)
    heads=[daily_head_panel(pd.Series(p,index=frame.index),frame['label'].iloc[:,0],[3,5],tradable=tradable.reindex(frame.index)) for p in [pa,pb]]
    result['selected_heads']={}
    for k in [3,5]:
        aa,bb=heads[0][k]['sets'],heads[1][k]['sets']
        if isinstance(aa,dict):
            assert set(aa)==set(bb)
            dates=sorted(aa);aa=[aa[d] for d in dates];bb=[bb[d] for d in dates]
        elif isinstance(aa,pd.Series):aa=aa.tolist();bb=bb.tolist()
        result['selected_heads'][str(k)]={'days':len(aa),'different_days':sum(set(x)!=set(y) for x,y in zip(aa,bb)),'mean_overlap':float(np.mean([len(set(x)&set(y))/k for x,y in zip(aa,bb)]))}
    out=BASE/'docs'/f'{PREFIX}-routes-{a}--{b}.json';write(out,result);print(json.dumps(result,indent=2))
